    });

    servers.push({
      close: async () => {
        wss.close();
        await new Promise<void>((resolve) => server.close(() => resolve()));
      },
    });

    let { body } = await httpGet(
      `http://localhost:${port}/tmpl.html`
    );
    expect(body).toContain("TEMPLATE_V1");

    await fs.writeFile(
      path.join(templatesDir, "default.hbs"),
